public class ExpenseDbContext : DbContext
{
    private readonly string _connectionString;
    private readonly string? _readReplicaConnectionString;

    public ExpenseDbContext(DbContextOptions options, IConfiguration config)
        : base(options)
    {
        _connectionString = config.GetConnectionString("DefaultConnection");
        _readReplicaConnectionString = config.GetConnectionString("ReadReplica");
    }

    public async Task<List<Expense>> GetExpensesForReportAsync(
        Guid userId, DateOnly from, DateOnly to, CancellationToken ct)
    {
        if (Database.IsRelational() && _readReplicaConnectionString != null)
        {
            var conn = new SqlConnection(_readReplicaConnectionString);
            return await conn.QueryAsync<Expense>(
                "SELECT * FROM Expenses WHERE UserId = @UserId AND Date BETWEEN @From AND @To",
                new { UserId = userId, From = from, To = to }, ct)
                .ContinueWith(t => t.Result.ToList());
        }

        return await Expenses
            .Where(e => e.UserId == userId && e.Date >= from && e.Date <= to)
            .ToListAsync(ct);
    }
}
